class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options: list[str] = []
        self._votes: dict[str, int] = {}
        self._voters: set[str] = set()
        self._total_votes: int = 0

    def add_option(self, option: str) -> None:
        if option not in self._votes:
            self._options.append(option)
            self._votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self._voters:
            raise ValueError(f"Voter '{voter}' has already voted.")
        if option not in self._votes:
            raise ValueError(f"Option '{option}' is not a valid option.")

        self._voters.add(voter)
        self._votes[option] += 1
        self._total_votes += 1

    def winner(self) -> str | None:
        if self._total_votes < 3:
            return None

        # Determine the winner based on the highest vote count.
        # In case of a tie, the option added last wins. By searching through
        # self._options in reverse order, any strictly greater vote count
        # will update the winner, preserving the latest-added option on ties.
        best_option = None
        max_votes = -1

        for option in reversed(self._options):
            count = self._votes[option]
            if count > max_votes:
                max_votes = count
                best_option = option

        return best_option
```

